function acceptanceProcessAlive(pid) {
  const value = Number(pid);
  if (!Number.isSafeInteger(value) || value <= 0) return false;
  try {
    process.kill(value, 0);
    return true;
  } catch (error) {
    return error?.code === 'EPERM';
  }
}

async function acquireAcceptanceRunLock() {
  await fsp.mkdir(path.dirname(ACCEPTANCE_RUN_LOCK_PATH), { recursive: true });
  const runId = ACCEPTANCE_RUN_ID;
  for (let attempt = 0; attempt < 4; attempt++) {
    let handle = null;
    try {
      handle = await fsp.open(ACCEPTANCE_RUN_LOCK_PATH, 'wx', 0o600);
      await handle.writeFile(JSON.stringify({
        schema: 'wx-summary.acceptance-run-lock.v1',
        pid: process.pid,
        run_id: runId,
        created_at: new Date().toISOString(),
      }), 'utf-8');
      await handle.sync();
      await handle.close();
      return { path: ACCEPTANCE_RUN_LOCK_PATH, run_id: runId };
    } catch (error) {
      await handle?.close().catch(() => {});
      if (error?.code !== 'EEXIST') throw error;
    }

    const stat = await fsp.stat(ACCEPTANCE_RUN_LOCK_PATH).catch(error => {
      if (error?.code === 'ENOENT') return null;
      throw error;
    });
    if (!stat) continue;
    let owner = null;
    try {
      owner = JSON.parse(await fsp.readFile(ACCEPTANCE_RUN_LOCK_PATH, 'utf-8'));
    } catch {
      owner = null;
    }
    const initializing = !owner && Date.now() - stat.mtimeMs < ACCEPTANCE_RUN_LOCK_INIT_GRACE_MS;
    if (initializing || acceptanceProcessAlive(owner?.pid)) {
      throw Object.assign(new Error(`acceptance_run_locked: another acceptance process is active (pid ${owner?.pid || 'initializing'})`), {
        code: 'acceptance_run_locked',
      });
    }
    const stalePath = `${ACCEPTANCE_RUN_LOCK_PATH}.stale-${crypto.randomUUID()}`;
    try {
      await fsp.rename(ACCEPTANCE_RUN_LOCK_PATH, stalePath);
      await fsp.rm(stalePath, { force: true });
    } catch (error) {
      if (!['ENOENT', 'EACCES', 'EPERM'].includes(error?.code)) throw error;
    }
  }
  throw Object.assign(new Error('acceptance_run_locked: could not acquire the acceptance process lock'), {
    code: 'acceptance_run_locked',
  });
}

async function releaseAcceptanceRunLock(lock = null) {
  if (!lock?.run_id || path.resolve(lock.path || '') !== path.resolve(ACCEPTANCE_RUN_LOCK_PATH)) return;
  let owner = null;
  try {
    owner = JSON.parse(await fsp.readFile(ACCEPTANCE_RUN_LOCK_PATH, 'utf-8'));
  } catch (error) {
    if (error?.code === 'ENOENT') return;
    throw error;
  }
  if (owner?.run_id !== lock.run_id || Number(owner?.pid) !== process.pid) return;
  await fsp.rm(ACCEPTANCE_RUN_LOCK_PATH, { force: true });
}

