async function cleanupAbandonedAcceptanceHistoryFixtures() {
  const outputs = path.join(ROOT, 'outputs');
  const entries = await fsp.readdir(outputs, { withFileTypes: true }).catch(error => {
    if (error?.code === 'ENOENT') return [];
    throw error;
  });
  for (const entry of entries) {
    if (!entry.isDirectory() || !/^acceptance-history-(?:digest-test|fixture-scope-regression)-/i.test(entry.name)) continue;
    const fixture = path.join(outputs, entry.name);
    const marker = path.join(fixture, '.wx-summary-acceptance-fixture');
    if (!await fsp.stat(marker).then(stat => stat.isFile(), () => false)) continue;
    await fsp.rm(fixture, { recursive: true, force: true });
  }
}

