function staleAssetGuardRoutesFromMain(mainJs = '') {
  const guardSource = mainJs.match(/function mutationRequiresFreshFrontendAsset[\s\S]*?return \[([\s\S]*?)\]\.includes\(pathname\);/)?.[1] || '';
  return new Set([...guardSource.matchAll(/'([^']+)'/g)].map(match => match[1]));
}

function staleAssetSideEffectGetRoutesFromMain(mainJs = '') {
  const guardFunction = mainJs.match(/function sideEffectGetRequiresFreshFrontendAsset[\s\S]*?\n}/)?.[0] || '';
  const guardSource = guardFunction.match(/\[([\s\S]*?)\]\.includes\(pathname\)/)?.[1] || '';
  return new Set([
    ...[...guardSource.matchAll(/'([^']+)'/g)].map(match => match[1]),
    ...[...guardFunction.matchAll(/pathname\.startsWith\('([^']+)'\)/g)].map(match => match[1]),
  ]);
}

function mutationRoutesFromMain(mainJs = '') {
  const routes = new Set();
  for (const line of mainJs.split(/\r?\n/)) {
    if (!line.includes("pathname === '/api/") || !/req\.method === '(POST|PUT|PATCH|DELETE)'/.test(line)) continue;
    const route = line.match(/pathname === '([^']+)'/)?.[1];
    const methods = [...line.matchAll(/req\.method === '([A-Z]+)'/g)].map(match => match[1]);
    if (route && methods.some(method => ['POST', 'PUT', 'PATCH', 'DELETE'].includes(method))) routes.add(route);
  }
  return routes;
}

function escapeRegex(text = '') {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function markdownTablePipeCount(line = '') {
  return (line.match(/(?<!\\)\|/g) || []).length;
}

function isMarkdownTableSeparator(line = '') {
  return /^\s*\|\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(line);
}

