          bytes: stat.size,
          mtimeMs: stat.mtimeMs,
          ctimeMs: stat.ctimeMs,
          birthtimeMs: stat.birthtimeMs,
          dev: stat.dev,
          ino: stat.ino,
          target_ctimeMs: stat.ctimeMs,
          target_birthtimeMs: stat.birthtimeMs,
          target_dev: stat.dev,
          target_ino: stat.ino,
