async function verifyFallbackChunkedMultimodalCompleteness() {
  const requests = [];
  let seen = 0;
  let chunkSuccess = 0;
  let mergeText = '';
  const server = http.createServer(async (req, res) => {
    const chunks = [];
    for await (const chunk of req) chunks.push(chunk);
    const body = JSON.parse(Buffer.concat(chunks).toString('utf-8') || '{}');
    seen++;
    const content = body.messages?.[1]?.content;
    const requestText = Array.isArray(content)
      ? content.map(part => part.text || '').join('\n')
      : String(content || '');
    const isMerge = requestText.includes('任务模式：merge');
    const systemText = String(body.messages?.[0]?.content || '');
    requests.push({ body, failed: seen === 1, requestText, systemText, isMerge });
    if (seen === 1) {
      res.writeHead(413, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: { message: 'payload too large' } }));
      return;
    }
    let payload;
    if (isMerge) {
      mergeText = [systemText, requestText].join('\n');
      payload = {
        headline: '合并完成',
        topics: [{ title: '分段合并议题', participants: ['小张', '小李'], summary: '保留两个分段里的独立结论。', need_followup: true }],
        mentions_me: [],
        todos: [
          { owner: '小张', item: '处理分段 1 的待办', deadline: '今天' },
          { owner: '小李', item: '处理分段 6 的待办', deadline: '明天' },
        ],
        links: [
          { title: '链接 1', url: 'https://example.com/chunk-1', summary: '第 1 段链接用途', from: '小张', time: '09:00' },
          { title: '链接 6', url: 'https://example.com/chunk-6', summary: '第 6 段链接用途', from: '小李', time: '09:05' },
        ],
      };
    } else {
      chunkSuccess++;
      const imageNumber = Number((requestText.match(/\[图片\s*(\d+)\]/)?.[1] || '').trim()) || 0;
      const minuteMatch = requestText.match(/09:(\d{2})/);
      const minuteNumber = minuteMatch ? Number(minuteMatch[1]) + 1 : 0;
      const chunkNumber = imageNumber || minuteNumber || chunkSuccess;
      payload = {
        headline: `分段 ${chunkNumber}`,
        topics: [{ title: `议题 ${chunkNumber}`, participants: [`成员 ${chunkNumber}`], summary: `第 ${chunkNumber} 段独立结论`, need_followup: chunkNumber % 2 === 0 }],
        mentions_me: [],
        todos: [{ owner: `成员 ${chunkNumber}`, item: `处理分段 ${chunkNumber} 的待办`, deadline: '' }],
        links: [{ title: `链接 ${chunkNumber}`, url: `https://example.com/chunk-${chunkNumber}`, summary: `第 ${chunkNumber} 段链接用途`, from: `成员 ${chunkNumber}`, time: `09:${String(chunkNumber - 1).padStart(2, '0')}` }],
      };
    }
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      choices: [{
        message: {
          content: JSON.stringify(payload),
        },
      }],
    }));
  });
  await listenLocalTestServer(server);
  try {
    const { port } = server.address();
    const imageMessages = Array.from({ length: 6 }, (_, i) => ({
      time: `2026-05-27 09:${String(i).padStart(2, '0')}`,
      sender: '小张',
      type: 'image',
      content: `[图片 ${i + 1}] https://example.com/chunk-${i + 1}`,
      media: { data_url: `data:image/png;base64,${'A'.repeat(60000)}`, mime: 'image/png' },
    }));
    const digest = await summarizeDigest({
      settings: {
        llm: {
          provider: 'openai',
          base_url: `http://127.0.0.1:${port}`,
          api_key: 'test-key',
          model: 'test-model',
          long_context_model: 'test-model',
          temperature: 0,
          timeout_ms: 10000,
          max_image_chars_per_call: 120000,
        },
        privacy: { attach_media_content: true },
      },
      groupName: '测试群',
      since: '2026-05-27 09:00',
      until: '2026-05-27 10:00',
      messages: imageMessages,
    });
    const successfulImageCount = requests.filter(r => !r.failed).reduce((n, r) => {
      const content = r.body.messages?.[1]?.content;
      return n + (Array.isArray(content) ? content.filter(part => part.type === 'image_url').length : 0);
    }, 0);
    assert.equal(successfulImageCount, imageMessages.length, 'fallback chunking must preserve every decoded image after a full request fails');
    assert.equal(requests.length, imageMessages.length + 2, 'failed full request should honor configured internal image chunk size, then merge chunk summaries');
    assert.ok(requests.some(r => r.isMerge), 'fallback chunking should finish with a merge request');
    assert.match(mergeText, /不要因为后段覆盖前段而丢掉链接、待办/, 'merge prompt should explicitly preserve earlier chunk links and todos');
    assert.match(mergeText, /处理分段 1 的待办[\s\S]*处理分段 6 的待办/, 'merge input should include todos from all chunk summaries');
    assert.match(mergeText, /https:\/\/example\.com\/chunk-1[\s\S]*https:\/\/example\.com\/chunk-6/, 'merge input should include links from all chunk summaries');
    assert.deepEqual(digest.todos.map(item => item.item), ['处理分段 1 的待办', '处理分段 6 的待办'], 'final merged digest should preserve distinct todos returned by merge');
    assert.deepEqual(digest.links.map(item => item.url), ['https://example.com/chunk-1', 'https://example.com/chunk-6'], 'final merged digest should preserve distinct links returned by merge');
  } finally {
    await new Promise(resolve => server.close(resolve));
  }
}

