async function verifyMarkdownTables() {
  const docs = [
    'README.md',
    'docs/用户手册.md',
    'docs/macOS使用指南.md',
  ];
  const failures = [];
  for (const relative of docs) {
    const lines = (await fsp.readFile(path.join(ROOT, relative), 'utf-8')).split(/\r?\n/);
    for (let i = 0; i < lines.length - 1; i++) {
      const header = lines[i];
      const separator = lines[i + 1];
      if (!header.trim().startsWith('|') || !separator.trim().startsWith('|')) continue;
      if (!isMarkdownTableSeparator(separator)) continue;
      const expected = markdownTablePipeCount(header);
      let j = i;
      while (j < lines.length && lines[j].trim().startsWith('|')) {
        const actual = markdownTablePipeCount(lines[j]);
        if (actual !== expected) {
          failures.push(`${relative}:${j + 1}: expected ${expected} table pipes, got ${actual}`);
        }
        j += 1;
      }
      i = j;
    }
  }
  assert.deepEqual(failures, [], 'Markdown tables in delivered docs should keep consistent column counts');
}

async function verifyLocalMarkdownLinks() {
  await assertLocalMarkdownLinksExist(await deliveredMarkdownDocs());
}

function runNodeScript(script, args = [], { timeoutMs = 30000 } = {}) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [script, ...args], {
      cwd: ROOT,
      stdio: ['ignore', 'pipe', 'pipe'],
      windowsHide: true,
    });
    let stdout = '';
    let stderr = '';
    let settled = false;
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      child.kill('SIGKILL');
      reject(new Error(`${script} timed out after ${timeoutMs}ms`));
    }, timeoutMs);
    child.stdout.setEncoding('utf-8');
    child.stderr.setEncoding('utf-8');
    child.stdout.on('data', chunk => { stdout += chunk; });
    child.stderr.on('data', chunk => { stderr += chunk; });
    child.on('error', error => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      reject(error);
    });
    child.on('close', code => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (code === 0) {
        resolve({ stdout, stderr });
        return;
      }
      reject(new Error((stderr || stdout || `${script} exited with ${code}`).trim()));
    });
  });
}

async function assertLocalMarkdownLinksExist(files) {
  const anchorCache = new Map();
  for (const file of files) {
    const text = stripMarkdownFencedCode(await fsp.readFile(file, 'utf-8'));
    const base = path.dirname(file);
    for (const match of text.matchAll(/!?\[[^\]]+\]\(([^)]+)\)/g)) {
      const rawTarget = String(match[1] || '').trim();
      if (!rawTarget || /^[a-z][a-z0-9+.-]*:/i.test(rawTarget)) continue;
      const targetWithoutTitle = rawTarget.match(/^<([^>]+)>$/)?.[1] || rawTarget.split(/\s+["'][^"']*["']\s*$/)[0];
      const [targetPath, rawFragment] = targetWithoutTitle.split('#');
      const resolved = targetPath ? path.resolve(base, decodeURIComponent(targetPath)) : file;
      const exists = await fsp.access(resolved).then(() => true).catch(() => false);
      assert.equal(exists, true, `${path.relative(ROOT, file)} has broken local markdown link: ${rawTarget}`);
      if (rawFragment) {
        const anchors = await markdownHeadingAnchors(resolved, anchorCache);
        const fragment = decodeURIComponent(rawFragment).toLowerCase();
        assert.equal(anchors.has(fragment), true, `${path.relative(ROOT, file)} has broken local markdown anchor: ${rawTarget}`);
      }
    }
  }
}

function stripMarkdownFencedCode(text) {
  return String(text || '').replace(/(^|\n)(`{3,}|~{3,})[^\n]*\n[\s\S]*?\n\2(?=\n|$)/g, '$1');
}

async function markdownHeadingAnchors(file, cache) {
  if (cache.has(file)) return cache.get(file);
  const text = stripMarkdownFencedCode(await fsp.readFile(file, 'utf-8'));
  const anchors = new Set();
  const seen = new Map();
  for (const match of text.matchAll(/^#{1,6}\s+(.+)$/gm)) {
    const base = markdownHeadingAnchor(match[1]);
    if (!base) continue;
    const count = seen.get(base) || 0;
    seen.set(base, count + 1);
    anchors.add(count === 0 ? base : `${base}-${count}`);
  }
  cache.set(file, anchors);
  return anchors;
}

function markdownHeadingAnchor(text) {
  return String(text || '')
    .trim()
    .replace(/\s+#+\s*$/, '')
    .toLowerCase()
    .replace(/[`*_~[\]()<>{}.,:;'"!?，。、“”‘’：；！（）【】《》]/g, '')
    .replace(/[^\p{L}\p{N}\s-]/gu, '')
    .trim()
    .replace(/\s+/g, '-');
}

