  assert.ok(wxdbSource.includes('moduleFunctionAddressTargetItems') && wxdbSource.includes('candidate_bridge_resolved_function_paths') && wxdbSource.includes('module_anchor_function_target_count'), 'deep wxdb diagnostics should turn resolved function buckets into runtime module-address targets');
