async function scanPackageDeps() {
  const pkg = JSON.parse(await fsp.readFile(path.join(ROOT, 'package.json'), 'utf-8'));
  const depNames = Object.keys({ ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) });
  for (const dep of depNames) {
    assert.equal(BANNED_DEPS.some(banned => dep.toLowerCase().includes(banned)), false, `banned dependency: ${dep}`);
  }
}

async function verifyGitIgnoreBoundaries() {
  const pkg = JSON.parse(await fsp.readFile(path.join(ROOT, 'package.json'), 'utf-8'));
  assert.equal(pkg.scripts?.prepare, 'node scripts/install-githooks.mjs', 'npm prepare should install the repository git hooks');
  const installer = await fsp.readFile(path.join(ROOT, 'scripts', 'install-githooks.mjs'), 'utf-8');
  assert.ok(installer.includes('core.hooksPath') && installer.includes('.githooks'), 'hook installer should configure git core.hooksPath');
  assert.ok(installer.includes('chmodSync(hook, 0o755)'), 'hook installer should restore executable permission on macOS/Linux');
  assert.equal(await gitConfigGet('core.hooksPath'), '.githooks', 'current repository should have the pre-commit hook enabled');

  const gitignore = await fsp.readFile(path.join(ROOT, '.gitignore'), 'utf-8');
  for (const expectedRule of [
    '/data/**',
    '!/data/settings.example.json',
    '/微信群消息总结-需求文档.md',
    '/superpowers/',
    '/docs/**',
    '!/docs/用户手册.md',
    '!/docs/macOS使用指南.md',
    '/scripts/collect-macos-acceptance-evidence.mjs',
    '/docs/assets/',
  ]) {
    assert.ok(gitignore.includes(expectedRule), `gitignore should preserve the minimal public boundary: ${expectedRule}`);
  }

  for (const ignoredPath of [
    'data/settings.json',
    'data/secrets.bin',
    'data/wxdb-keys.bin',
    'outputs/digests/index.json',
    '微信群消息总结-需求文档.md',
    'docs/CODEX执行指令.md',
    'docs/完成度审计.md',
    'docs/assets/ui-digest.png',
    'superpowers/docs/plans/internal.md',
    'scripts/collect-macos-acceptance-evidence.mjs',
  ]) {
    const result = await runGit(['check-ignore', '--no-index', '-q', '--', ignoredPath], { rejectOnNonZero: false });
    assert.equal(result.code, 0, `local-only path should stay ignored: ${ignoredPath}`);
  }
  for (const publicPath of [
    'data/settings.example.json',
    'docs/用户手册.md',
    'docs/macOS使用指南.md',
    'tests/acceptance/static-checks.mjs',
    'scripts/capture-weixin-binary-evidence.mjs',
    'scripts/install-githooks.mjs',
    '.githooks/pre-commit',
  ]) {
    const result = await runGit(['check-ignore', '--no-index', '-q', '--', publicPath], { rejectOnNonZero: false });
    assert.equal(result.code, 1, `public source or documentation should stay visible to git: ${publicPath}`);
  }

  assert.equal(await gitTrackedFileMode('启动.command'), '100755', '启动.command should be executable after clone');
  const gitattributes = await fsp.readFile(path.join(ROOT, '.gitattributes'), 'utf-8');
  assert.ok(gitattributes.includes('*.command text eol=lf'), 'macOS launchers should use LF line endings');
  assert.ok(gitattributes.includes('.githooks/pre-commit text eol=lf'), 'pre-commit hook should use LF line endings');
  assert.ok(gitattributes.includes('*.cmd text eol=crlf'), 'Windows launchers should use CRLF line endings');
  assert.ok(gitattributes.includes('*.ps1 text eol=crlf'), 'PowerShell scripts should use CRLF line endings');
  assert.equal(await gitAttributeValue('eol', '启动.command'), 'lf', '启动.command should resolve to LF');
  assert.equal(await gitAttributeValue('eol', '.githooks/pre-commit'), 'lf', 'pre-commit hook should resolve to LF');
  assert.equal(await gitAttributeValue('eol', '启动.cmd'), 'crlf', '启动.cmd should resolve to CRLF');
  assert.equal(await gitAttributeValue('eol', 'src/tray/wx-summary-tray.ps1'), 'crlf', 'tray helper should resolve to CRLF');

  const hook = await fsp.readFile(path.join(ROOT, '.githooks', 'pre-commit'), 'utf-8');
  assert.ok(hook.includes('blocked_paths') && hook.includes("grep -Ev '^data/settings\\.example\\.json$'") && hook.includes('^data/') && hook.includes('^outputs/'), 'pre-commit should reject runtime data while allowing the example settings file');
  assert.ok(hook.includes('^docs/assets/'), 'pre-commit should reject generated documentation screenshots');
  assert.ok(hook.includes('git cat-file -s') && hook.includes('5242880'), 'pre-commit should reject oversized staged files');
  assert.ok(hook.includes('grep -I -nE'), 'pre-commit should scan only text content');
  assert.ok(hook.includes('impl_files') && hook.includes('secret_scan_files'), 'pre-commit should scope implementation and secret scans');
  assert.ok(hook.includes("grep -Ev '^(tests/") && hook.includes('rm -f "$changed_files" "$impl_files" "$secret_scan_files"'), 'pre-commit should allow fake test secrets and clean temporary lists');

  await runPreCommitWithTemporaryIndex([
    'README.md',
    'docs/macOS使用指南.md',
    'docs/用户手册.md',
    'tests/acceptance/static-checks.mjs',
    'scripts/capture-weixin-binary-evidence.mjs',
    'scripts/install-githooks.mjs',
    '.githooks/pre-commit',
  ], { expectCode: 0 });
  await runPreCommitWithTemporaryIndex(['outputs/.tmp/precommit-blocked-runtime.json'], {
    expectCode: 1,
    expectedOutput: /runtime, media, package or secret path staged/,
  });
}

async function runPreCommitWithTemporaryIndex(files, { expectCode = 0, expectedOutput = null } = {}) {
  const indexFile = path.join(os.tmpdir(), `wx-summary-precommit-${process.pid}-${crypto.randomUUID()}.index`);
  const env = { ...process.env, GIT_INDEX_FILE: indexFile };
  try {
    await runGit(['read-tree', 'HEAD'], { env });
    const existingFiles = [];
    const syntheticFiles = [];
    for (const file of files) {
      if (fs.existsSync(path.join(ROOT, file))) existingFiles.push(file);
      else syntheticFiles.push(file);
    }
    if (existingFiles.length) {
      await runGit(['add', '--', ...existingFiles], { env });
    }
    let syntheticBlob = null;
    for (const file of syntheticFiles) {
      syntheticBlob ||= (await runGit(['rev-parse', 'HEAD:README.md'], { env })).stdout.trim();
      await runGit(['update-index', '--add', '--cacheinfo', `100644,${syntheticBlob},${file}`], { env });
    }
    const result = await runCommand('sh', ['.githooks/pre-commit'], { env, rejectOnNonZero: false });
    assert.equal(result.code, expectCode, `pre-commit exit code mismatch for ${files.join(', ')}:\n${result.stdout}${result.stderr}`);
    if (expectedOutput) {
      assert.match(`${result.stdout}\n${result.stderr}`, expectedOutput, 'pre-commit output should explain the expected allow/block reason');
    }
  } finally {
    await fsp.rm(indexFile, { force: true }).catch(() => {});
  }
}

function runGit(args, options = {}) {
  return runCommand('git', args, options);
}

function runCommand(command, args = [], { env = process.env, rejectOnNonZero = true } = {}) {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, {
      cwd: ROOT,
      env,
      stdio: ['ignore', 'pipe', 'pipe'],
      windowsHide: true,
    });
    let stdout = '';
    let stderr = '';
    child.stdout.setEncoding('utf-8');
    child.stderr.setEncoding('utf-8');
    child.stdout.on('data', chunk => { stdout += chunk; });
    child.stderr.on('data', chunk => { stderr += chunk; });
    child.on('error', reject);
    child.on('exit', code => {
      const result = { code, stdout, stderr };
      if (code !== 0 && rejectOnNonZero) {
        reject(new Error((stderr || stdout || `${command} exited with ${code}`).trim()));
        return;
      }
      resolve(result);
    });
  });
}

function gitConfigGet(name) {
  return new Promise((resolve, reject) => {
    const child = spawn('git', ['config', '--get', name], {
      cwd: ROOT,
      stdio: ['ignore', 'pipe', 'pipe'],
      windowsHide: true,
    });
    let stdout = '';
    let stderr = '';
    child.stdout.setEncoding('utf-8');
    child.stderr.setEncoding('utf-8');
    child.stdout.on('data', chunk => { stdout += chunk; });
    child.stderr.on('data', chunk => { stderr += chunk; });
    child.on('error', reject);
    child.on('exit', code => {
      if (code !== 0) {
        reject(new Error((stderr || stdout || `git config exited with ${code}`).trim()));
        return;
      }
      resolve(stdout.trim().replace(/\\/g, '/'));
    });
  });
}

function gitTrackedFileMode(file) {
  return new Promise((resolve, reject) => {
    const child = spawn('git', ['ls-files', '--stage', '--', file], {
      cwd: ROOT,
      stdio: ['ignore', 'pipe', 'pipe'],
      windowsHide: true,
    });
    let stdout = '';
    let stderr = '';
    child.stdout.setEncoding('utf-8');
    child.stderr.setEncoding('utf-8');
    child.stdout.on('data', chunk => { stdout += chunk; });
    child.stderr.on('data', chunk => { stderr += chunk; });
    child.on('error', reject);
    child.on('exit', code => {
      if (code !== 0) {
        reject(new Error((stderr || stdout || `git ls-files exited with ${code}`).trim()));
        return;
      }
      const mode = stdout.trim().split(/\s+/)[0] || '';
      resolve(mode);
    });
  });
}

async function gitAttributeValue(attribute, file) {
  const result = await runGit(['check-attr', attribute, '--', file]);
  const match = result.stdout.trim().match(new RegExp(`:\\s*${escapeRegex(attribute)}:\\s*(\\S+)\\s*$`));
  return match?.[1] || '';
}

