    assert.equal(recoveredAfterCleanupCrash.llm.api_key, originalApiKey, 'rolled_back cleanup recovery should keep the already-restored secret generation');
    assert.equal(fs.existsSync(journalFile), false, 'rolled_back recovery should finish removing the terminal transaction journal without requiring backups');

