      assert.deepEqual(await fsp.readFile(settingsFile), halfSettingsBytes, 'corrupt-journal recovery must not rewrite current settings before transaction provenance is known');
      assert.deepEqual(await fsp.readFile(secretsFile), halfSecretsBytes, 'corrupt-journal recovery must not rewrite current secrets before transaction provenance is known');
