    assert.deepEqual(await fsp.readFile(secretsFile), halfSecretsBytes, 'prepared recovery must leave both current generations untouched when backup preflight fails');
    assert.equal(fs.existsSync(journalFile), true, 'an unsafe prepared transaction must retain its journal for the next recovery attempt');
    assert.equal(fs.existsSync(settingsBackup), true, 'an unsafe prepared transaction must retain any surviving backup evidence');
