  const writeRetentionManifest = async ({ originalPath, stagedPath, role, expectedVersion, fileVersion }) => {
    const transactionId = stagedPath.match(/\.retention-delete-([0-9a-f-]+)\.pending$/i)?.[1] || '';
    assert.match(transactionId, /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i);
    await fsp.writeFile(`${stagedPath}.transaction.json`, JSON.stringify({
      schema: 'wx-summary.retention-delete.v1',
      version: 1,
      transaction_id: transactionId,
      output_dir_identity: retentionOutputIdentity,
      original_relative_path: path.relative(dir, originalPath).replace(/\\/g, '/'),
      staged_relative_path: path.relative(dir, stagedPath).replace(/\\/g, '/'),
      role,
      expected_version: expectedVersion,
      file_version: fileVersion,
      prepared_at: new Date().toISOString(),
    }));
  };
