  assert.equal(fs.existsSync(recoverPng), true, 'retention recovery should restore a staged primary artifact before normal cleanup reads the index');
  assert.equal(fs.existsSync(recoverDigest), true, 'retention recovery should restore a staged digest sidecar before normal cleanup reads the index');
  assert.equal(fs.existsSync(recoverPngPending), false, 'retention recovery should consume the staged primary filename');
  assert.equal(fs.existsSync(recoverDigestPending), false, 'retention recovery should consume the staged sidecar filename');
  assert.equal(fs.existsSync(`${recoverPngPending}.transaction.json`), false, 'retention recovery should remove the primary transaction manifest after a verified restore');
  assert.equal(fs.existsSync(`${recoverDigestPending}.transaction.json`), false, 'retention recovery should remove the sidecar transaction manifest after a verified restore');
