  assert.equal(fs.existsSync(dependencySourceItem.file_path), true, 'the source PNG should remain while a retained Markdown row depends on the source history item');
  assert.equal(fs.existsSync(dependencySourceItem.digest_path), true, 'the source digest JSON should remain readable while a retained Markdown row requires source validation');
  assert.equal(fs.existsSync(dependencyMdItem.file_path), true, 'the retained Markdown file should remain usable together with its source summary');
  const expiredDependencyRows = dependencyKept.map(item => ({ ...item, created_at: '2000-01-01T00:00:00.000Z' }));
