  assert.equal(fs.existsSync(dependencyMdItem.file_path), false, 'the expired Markdown file should be deleted with its now-unreferenced source summary');
  await fsp.rm(dependencyRoot, { recursive: true, force: true });

  const lineageDir = path.join(ROOT, 'outputs', 'acceptance-retention-lineage-test', 'digests');
