  assert.equal(fs.existsSync(unownedRerenderPng), true, 'retention must not delete a rerender-looking PNG without a verified wx-summary commit marker');
  assert.equal(fs.existsSync(unownedRerenderDigest), true, 'retention must not delete an unverified rerender-looking digest JSON');
  assert.equal(fs.existsSync(unownedRerenderMarker), true, 'retention must not delete an unverified rerender-looking marker');
