      assert.deepEqual(terminalSummaries.map(item => item.status), ['saved', 'error'], 'batch recovery listing should expose ordered saved/error terminal states without returning every full digest at once');
      assert.equal(terminalSummaries[0].item.relative_path, terminalSavedItem.relative_path, 'batch recovery listing should return the committed history item for idempotent saved results');
      assert.equal(Object.hasOwn(terminalSummaries[0], 'digest'), false, 'batch recovery listing should not duplicate full terminal digest payloads');
      const terminalRecoverySnapshot = __mainInternals.digestTerminalRecoverySnapshot();
