  assert.equal(profileAttempts.filter(item => item.profile.id === 'wcdb_sha256_page4096').length, 8, 'SHA256 fallback should cover the complete high-confidence prefix');
  assert.equal(profileAttempts.filter(item => item.profile.id === 'sqlcipher4_sha256_page4096').length, 8, 'SQLCipher4 SHA256 fallback should cover the complete high-confidence prefix');
  assert.equal(profileAttempts.filter(item => item.profile.id === 'wcdb_legacy_sha1_no_hmac_page4096').length, 8, 'no-HMAC SHA1 fallback should cover the complete high-confidence prefix');
  assert.equal(profileAttempts.filter(item => item.profile.id === 'wcdb_sha256_no_hmac_page4096').length, 8, 'no-HMAC SHA256 fallback should cover the complete high-confidence prefix');
  assert.ok(profileAttempts.length <= 96, 'SQLCipher compatibility validation must keep a bounded total attempt plan even for thousands of memory candidates');
  assert.ok(source.includes('profile_fallback_bounded: true') && source.includes('profile_fallback_omitted_candidate_count') && source.includes('fallback_key_priority') && source.includes('orderedKeys.slice(0, priorityCount)') && source.includes('sqlCipherDefaultProfileLimit({ fallback_profiles })') && source.includes('.slice(0, SQLCIPHER_VALIDATION_MAX_ATTEMPTS)') && !source.includes('profile_fallback_unbounded: true') && !source.includes('orderedKeys.slice(priorityCount)'), 'SQLCipher compatibility profiles should reserve a bounded total attempt plan and report omitted candidates instead of allowing an unbounded candidate/profile cross-product');
